caddy_spec.matcher_snippet:
# BUBBLE GATE — redirect pure consumers to banana pore
# Match by behavioral fingerprint (opsonize tag from skunky-ingest)
@bubbled {
    header X-Opsonize-Tag opsonized:coordinated:*
    not path /banana.html
    not path /api/*
    not path /assets/*
}
rewrite @bubbled /banana.html
